<script setup>
import {ref} from 'vue'
import {onShow} from '@dcloudio/uni-app'
import {request} from '../../utils/request'
import ListeningSummaryCard from '../../components/ListeningSummaryCard.vue'
const rows=ref([]),page=ref(1),total=ref(0),loading=ref(false),error=ref(''),detail=ref(null)
async function load(reset=true){if(loading.value)return;loading.value=true;error.value='';try{const next=reset?1:page.value+1;const d=await request({url:'/api/emotion/sessions',data:{page:next}});rows.value=reset?d.records:[...rows.value,...d.records];total.value=d.total;page.value=next}catch(e){error.value=e.message||'加载失败'}finally{loading.value=false}}
async function view(row){try{detail.value=await request({url:'/api/emotion/sessions/'+row.sessionId})}catch(e){error.value=e.message}}
function remove(id){uni.showModal({title:'删除倾听记录',content:'会话与消息将被删除，独立安全审计按规则保留。是否继续？',success:async r=>{if(!r.confirm)return;try{await request({url:'/api/emotion/sessions/'+id,method:'DELETE'});detail.value=null;await load()}catch(e){error.value=e.message}}})}
onShow(()=>load())
async function resume(id){try{await request({url:'/api/emotion/sessions/'+id+'/state',method:'PUT',data:{action:'RESUME'}});uni.navigateTo({url:'/pages/emotion/chat?sessionId='+id})}catch(e){error.value=e.message}}
</script>
<template><view class="history-page"><text class="heading">你的倾听记录</text><text class="intro">只有你能查看这些对话。可以回顾，也可以选择删除。</text><text v-if="error" class="error">{{error}}</text><button v-if="error" size="mini" @click="load()">重试</button><view v-if="detail" class="card"><button size="mini" @click="detail=null">返回列表</button><view v-for="(m,i) in detail.messages" :key="i" class="message"><text class="role">{{m.role==='user'?'我':'小织'}}</text><text>{{m.content}}</text></view><ListeningSummaryCard :session-id="detail.session.sessionId" :session-status="detail.session.status" /><button @click="resume(detail.session.sessionId)">继续这次倾听</button><text class="intro">{{detail.session.summary||'尚未形成摘要'}}</text><button @click="remove(detail.session.sessionId)">删除本次记录</button></view><template v-else><view v-for="r in rows" :key="r.sessionId" class="card" @click="view(r)"><text class="date">{{String(r.startTime||'').replace('T',' ').slice(0,16)}}</text><text>{{r.summary||'一次倾听对话'}}</text><text class="open">查看对话 →</text></view><text v-if="!loading&&!rows.length&&!error" class="intro">还没有倾听记录，想聊时小织都在。</text><button v-if="rows.length<total" :loading="loading" @click="load(false)">加载更多</button></template><text class="intro">本系统不能替代专业心理咨询</text></view></template>
<style scoped>.history-page{padding:32rpx;display:flex;flex-direction:column;gap:24rpx;min-height:100vh;max-width:880px;margin:0 auto;box-sizing:border-box;width:100%;background:#f5f8f5}.heading{font-size:40rpx;font-weight:700;color:#203f35}.intro{font-size:25rpx;color:#697a72;line-height:1.8}.card{padding:30rpx;border-radius:24rpx;background:white;display:flex;flex-direction:column;gap:20rpx;font-size:28rpx;line-height:1.8}.date,.role{font-size:24rpx;color:#697a72}.message{display:flex;flex-direction:column;gap:10rpx;padding-bottom:24rpx;border-bottom:1px solid #edf1ed;white-space:pre-wrap}.open{color:#2f7566;font-size:25rpx}.error{color:#a73d3d}</style>
